#include <string_view>
#include "common/exception.h"

namespace bustub {

template <class T>
auto Trie::Get(std::string_view key) const -> const T * {
  auto node = root_;
  for (char c : key) {
    if (node == nullptr) {
      return nullptr;
    }
    auto it = node->children_.find(c);
    if (it == node->children_.end()) {
      return nullptr;
    }
    node = it->second;
  }
  if (node == nullptr || !node->is_value_node_) {
    return nullptr;
  }
  const auto *value_node = dynamic_cast<const TrieNodeWithValue<T> *>(node.get());
  if (value_node == nullptr) {
    return nullptr;
  }
  return value_node->value_.get();
}

template <class T>
auto Trie::Put(std::string_view key, T value) const -> Trie {
  auto new_root = root_ == nullptr ? std::make_unique<TrieNode>() : root_->Clone();
  auto *cur = new_root.get();
  for (char c : key) {
    auto it = cur->children_.find(c);
    std::unique_ptr<TrieNode> child;
    if (it != cur->children_.end()) {
      child = it->second->Clone();
    } else {
      child = std::make_unique<TrieNode>();
    }
    auto *child_ptr = child.get();
    cur->children_[c] = std::shared_ptr<const TrieNode>(std::move(child));
    cur = child_ptr;
  }
  auto value_ptr = std::make_shared<T>(std::move(value));
  std::map<char, std::shared_ptr<const TrieNode>> children(cur->children_.begin(), cur->children_.end());
  auto new_node = std::make_unique<TrieNodeWithValue<T>>(std::move(children), std::move(value_ptr));
  auto *new_node_ptr = new_node.get();
  if (key.empty()) {
    new_root = std::move(new_node);
  } else {
    auto *parent = new_root.get();
    for (size_t i = 0; i + 1 < key.size(); i++) {
      parent = const_cast<TrieNode *>(parent->children_.at(key[i]).get());
    }
    parent->children_[key.back()] = std::shared_ptr<const TrieNode>(std::move(new_node));
  }
  (void)new_node_ptr;
  return Trie(std::shared_ptr<const TrieNode>(std::move(new_root)));
}

template <class T>
auto Trie::Remove(std::string_view key) const -> Trie {
  if (root_ == nullptr) {
    return Trie(nullptr);
  }
  std::vector<std::shared_ptr<const TrieNode>> path;
  auto node = root_;
  for (char c : key) {
    path.push_back(node);
    auto it = node->children_.find(c);
    if (it == node->children_.end()) {
      return *this;
    }
    node = it->second;
  }
  if (node == nullptr || !node->is_value_node_) {
    return *this;
  }
  auto new_root = root_->Clone();
  auto *cur = new_root.get();
  for (size_t i = 0; i < key.size(); i++) {
    auto *next = const_cast<TrieNode *>(cur->children_.at(key[i]).get());
    auto cloned = next->Clone();
    cur->children_[key[i]] = std::shared_ptr<const TrieNode>(std::move(cloned));
    cur = const_cast<TrieNode *>(cur->children_.at(key[i]).get());
  }
  if (cur->children_.empty()) {
    cur->is_value_node_ = false;
  } else {
    auto children = cur->children_;
    auto *parent = new_root.get();
    for (size_t i = 0; i + 1 < key.size(); i++) {
      parent = const_cast<TrieNode *>(parent->children_.at(key[i]).get());
    }
    if (key.empty()) {
      new_root = std::make_unique<TrieNode>(std::move(children));
    } else {
      parent->children_[key.back()] = std::make_shared<const TrieNode>(std::move(children));
    }
  }
  return Trie(std::shared_ptr<const TrieNode>(std::move(new_root)));
}

